import React, { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useCompany } from '../context/CompanyContext';
import { Client, DeliveryNote } from '../types';
import {
  getDeliveryNote, updateDeliveryNote, createDeliveryNote, getNextDeliveryNoteNumber,
} from '../services/api';
import ClientPicker from '../components/Quotation/ClientPicker';
import { ArrowLeft, Save, Plus } from 'lucide-react';
import LineItemsEditor from '../components/common/LineItemsEditor';
import DocumentPreview, { PreviewColumn, PreviewToggleButton, usePreviewToggle } from '../components/Document/DocumentPreview';
import DeliveryNoteDocument from '../components/Delivery/DeliveryNoteDocument';

/** Today as a local 'YYYY-MM-DD' (toISOString would use UTC). */
const localToday = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};

/**
 * Create / edit page for delivery notes. DN don't carry money (no totals,
 * no taxes, no terms), so the form is just: number / date / client info /
 * line items. Items are { description, quantity }.
 *
 * `/edit-delivery-note/:id` edits an existing note; `/new-delivery-note`
 * creates a standalone one (not generated from a quotation).
 */
const EditDeliveryNote: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const isNew = !id;
  const navigate = useNavigate();
  const { selectedCompany } = useCompany();

  const [data, setData] = useState<Partial<DeliveryNote>>({});
  const [initialLoading, setInitialLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [showPreview, togglePreview] = usePreviewToggle();
  const [error, setError] = useState('');

  useEffect(() => {
    if (isNew) {
      if (!selectedCompany) return;
      let alive = true;
      setInitialLoading(true);
      setData({
        company_id: selectedCompany.id,
        delivery_note_number: '',
        client_name: '',
        date: localToday(),
        items: [{ description: '', quantity: 1 }],
      });
      getNextDeliveryNoteNumber(selectedCompany.id)
        .then(({ deliveryNoteNumber }) => {
          if (alive) setData((prev) => ({ ...prev, delivery_note_number: prev.delivery_note_number || deliveryNoteNumber }));
        })
        .catch(() => { /* user can type a number */ })
        .finally(() => { if (alive) setInitialLoading(false); });
      return () => { alive = false; };
    }
    (async () => {
      try {
        const dn = await getDeliveryNote(parseInt(id!, 10));
        setData(dn);
      } catch (e) {
        console.error(e);
        setError('Failed to load delivery note.');
      } finally {
        setInitialLoading(false);
      }
    })();
  }, [id, isNew, selectedCompany]);

  // Picking an existing client fills their details and links client_id so the
  // backend doesn't create a duplicate client record.
  const handleClientSelected = (client: Client) => {
    setData((prev) => ({
      ...prev,
      client_id: client.id,
      client_name: client.name,
      client_address: client.address || prev.client_address || '',
      client_email: client.email || prev.client_email || '',
      client_phone: client.phone || prev.client_phone || '',
    }));
  };

  const handleChange = (field: keyof DeliveryNote, value: any) => {
    setData((prev) => ({ ...prev, [field]: value }));
  };

  const addItem = () => {
    setData((prev) => ({
      ...prev,
      items: [...(prev.items || []), { description: '', quantity: 1 }],
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data.delivery_note_number?.trim()) {
      alert('Please enter a delivery note number.');
      return;
    }
    if (!data.client_name?.trim()) {
      alert('Please enter a client name.');
      return;
    }
    if (!data.items || data.items.length === 0) {
      alert('Please add at least one item.');
      return;
    }
    if (data.items.some((it) => !String(it.description || '').trim())) {
      alert('Please enter a description for every item.');
      return;
    }

    setSaving(true);
    try {
      if (isNew) {
        const created = await createDeliveryNote({ ...data, company_id: selectedCompany!.id });
        navigate(`/delivery-note/${created.id}`);
      } else {
        await updateDeliveryNote(parseInt(id!, 10), data);
        navigate(`/delivery-note/${id}`);
      }
    } catch (err: any) {
      const message =
        err?.response?.data?.error ||
        err?.response?.data?.message ||
        `Failed to ${isNew ? 'create' : 'update'} delivery note. Please try again.`;
      alert(message);
    } finally {
      setSaving(false);
    }
  };

  if (isNew && !selectedCompany) {
    return (
      <div className="text-center py-12 text-gray-600">Select a company to create a delivery note.</div>
    );
  }

  if (initialLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-gray-300" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-center py-12">
        <p className="text-gray-600 mb-4">{error}</p>
        <button onClick={() => navigate('/delivery-history')} className="text-blue-600 hover:underline">
          Back to Delivery Notes
        </button>
      </div>
    );
  }

  return (
    <div className={showPreview ? 'max-w-[1700px] mx-auto' : 'max-w-5xl mx-auto'}>
      <div className="mb-8 flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <button
            onClick={() => navigate(-1)}
            className="inline-flex items-center px-4 py-2 text-gray-600 hover:text-gray-900"
          >
            <ArrowLeft className="h-4 w-4 mr-2" />
            Back
          </button>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">{isNew ? 'New Delivery Note' : 'Edit Delivery Note'}</h1>
            <p className="text-gray-600 mt-1">
              {isNew ? `For ${selectedCompany!.name}` : `Editing ${data.delivery_note_number}`}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-3">
        <PreviewToggleButton show={showPreview} onToggle={togglePreview} />
        <button
          onClick={handleSubmit}
          disabled={saving}
          className="inline-flex items-center px-6 py-3 rounded-lg bg-indigo-600 text-white hover:bg-indigo-700 disabled:opacity-50"
        >
          {saving ? (
            <>
              <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2" />
              Saving...
            </>
          ) : (
            <>
              <Save className="h-4 w-4 mr-2" />
              {isNew ? 'Create Delivery Note' : 'Save Changes'}
            </>
          )}
        </button>
        </div>
      </div>

      <div className={showPreview ? 'grid grid-cols-1 xl:grid-cols-2 gap-8 items-start' : ''}>
      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Delivery Note details */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <h2 className="text-xl font-semibold mb-6">Delivery Note Details</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Field
              label="Delivery Note Number *"
              value={data.delivery_note_number || ''}
              onChange={(v) => handleChange('delivery_note_number', v)}
              placeholder="e.g. EH-DN-0001"
              required
            />
            <Field
              label="Date *"
              type="date"
              value={data.date?.split('T')[0] || ''}
              onChange={(v) => handleChange('date', v)}
              required
            />
          </div>
        </div>

        {/* Client info */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <h2 className="text-xl font-semibold mb-6">Client Information</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {isNew ? (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Client Name *</label>
                <ClientPicker
                  companyId={selectedCompany!.id}
                  value={data.client_name || ''}
                  onChange={(name) => {
                    // Typing a new name breaks any picked-client link.
                    setData((prev) => ({ ...prev, client_id: null, client_name: name }));
                  }}
                  onSelect={handleClientSelected}
                  required
                />
              </div>
            ) : (
              <Field
                label="Client Name *"
                value={data.client_name || ''}
                onChange={(v) => handleChange('client_name', v)}
                required
              />
            )}
            <Field
              label="Email"
              type="email"
              value={data.client_email || ''}
              onChange={(v) => handleChange('client_email', v)}
            />
            <Field
              label="Phone"
              type="tel"
              value={data.client_phone || ''}
              onChange={(v) => handleChange('client_phone', v)}
            />
            <TextField
              label="Address"
              value={data.client_address || ''}
              onChange={(v) => handleChange('client_address', v)}
              rows={3}
            />
          </div>
        </div>

        {/* Items */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-semibold">Items</h2>
            <button
              type="button"
              onClick={addItem}
              className="inline-flex items-center px-3 py-1.5 text-sm rounded-lg bg-indigo-600 text-white hover:bg-indigo-700"
            >
              <Plus className="h-4 w-4 mr-1.5" />
              Add Item
            </button>
          </div>

          <div className="space-y-3">
            {(data.items || []).length > 0 && (
              <LineItemsEditor
                items={data.items || []}
                onChange={(items) => setData((prev) => ({ ...prev, items }))}
                priceKey={null}
                newItem={() => ({ description: '', quantity: 1 })}
                descriptionPlaceholder="What is being delivered…"
              />
            )}

            {(!data.items || data.items.length === 0) && (
              <div className="text-center py-8 border-2 border-dashed border-gray-300 rounded-lg">
                <p className="text-gray-600 mb-3">No items in this delivery note</p>
                <button
                  type="button"
                  onClick={addItem}
                  className="inline-flex items-center px-3 py-1.5 text-sm rounded-lg bg-indigo-600 text-white hover:bg-indigo-700"
                >
                  <Plus className="h-4 w-4 mr-1.5" />
                  Add Item
                </button>
              </div>
            )}
          </div>
        </div>
      </form>
        {showPreview && selectedCompany && (
          <PreviewColumn>
            <DocumentPreview watch={[data, selectedCompany]}>
              <DeliveryNoteDocument
                data={{
                  delivery_note_number: data.delivery_note_number,
                  client_name: data.client_name,
                  client_address: data.client_address,
                  client_email: data.client_email,
                  client_phone: data.client_phone,
                  date: data.date,
                  items: (data.items || []).map((it) => ({ description: it.description, quantity: Number(it.quantity) || 0 })),
                  invoice_number: (data as any).invoice_number || null,
                }}
                company={{
                  name: selectedCompany.name,
                  address: selectedCompany.address,
                  tpin: selectedCompany.tpin,
                  logo_url: selectedCompany.quote_logo_url || selectedCompany.logo_url,
                  primary_color: selectedCompany.primary_color,
                  secondary_color: selectedCompany.secondary_color,
                  template: selectedCompany.template,
                  letterhead: selectedCompany.letterhead,
                }}
              />
            </DocumentPreview>
          </PreviewColumn>
        )}
      </div>
    </div>
  );
};

const Field: React.FC<{
  label: string;
  value: string;
  onChange: (v: string) => void;
  type?: string;
  placeholder?: string;
  required?: boolean;
}> = ({ label, value, onChange, type = 'text', placeholder, required }) => (
  <div>
    <label className="block text-sm font-medium text-gray-700 mb-2">{label}</label>
    <input
      type={type}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      required={required}
      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
    />
  </div>
);

const TextField: React.FC<{
  label: string;
  value: string;
  onChange: (v: string) => void;
  rows?: number;
}> = ({ label, value, onChange, rows = 3 }) => (
  <div>
    <label className="block text-sm font-medium text-gray-700 mb-2">{label}</label>
    <textarea
      value={value}
      onChange={(e) => onChange(e.target.value)}
      rows={rows}
      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
    />
  </div>
);

export default EditDeliveryNote;
