import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useCompany } from '../context/CompanyContext';
import { InvoiceItem, Invoice, DiscountType } from '../types';
import DiscountInput from '../components/common/DiscountInput';
import { getInvoice, updateInvoice } from '../services/api';
import {
  computeTotals,
  formatCurrency,
  formatNumber,
  documentVatRate,
  toDateInput,
} from '../utils/calculations';
import VatControl from '../components/common/VatControl';
import { Save, ArrowLeft, Plus, Calculator } from 'lucide-react';
import LineItemsEditor from '../components/common/LineItemsEditor';
import { brandColorFor } from '../utils/colors';
import { useTheme } from '../context/ThemeContext';
import DocumentPreview, { PreviewColumn, PreviewToggleButton, usePreviewToggle } from '../components/Document/DocumentPreview';
import InvoiceDocument from '../components/Invoice/InvoiceDocument';
import { UnitInput } from '../components/common/MoneyInput';

const EditInvoice: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { selectedCompany } = useCompany();
  const { theme } = useTheme();
  const [loading, setLoading] = useState(false);
  const [showPreview, togglePreview] = usePreviewToggle();
  const [initialLoading, setInitialLoading] = useState(true);
  const [invoiceData, setInvoiceData] = useState<Partial<Invoice>>({});
  // The invoice's own tax rates (as saved), not the company's current ones,
  // so editing never adds or changes VAT by itself.
  const [vatRate, setVatRate] = useState(0);
  const [ppdaRate, setPpdaRate] = useState(0);

  useEffect(() => {
    const loadInvoice = async () => {
      if (!id) return;

      try {
        const data = await getInvoice(parseInt(id));
        setInvoiceData({ ...data, date: toDateInput(data.date) });
        setVatRate(documentVatRate(data));
        const base = (Number(data.subtotal) || 0) - (Number(data.discount_amount) || 0);
        setPpdaRate(base > 0 ? (Number(data.ppda_amount) || 0) / base : 0);
      } catch (error) {
        console.error('Error loading invoice:', error);
        alert('Failed to load invoice');
        navigate('/invoice-history');
      } finally {
        setInitialLoading(false);
      }
    };

    loadInvoice();
  }, [id, navigate]);

  const handleInputChange = (field: string, value: any) => {
    setInvoiceData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleItemsChange = (items: InvoiceItem[]) => {
    const updatedItems = items.map(item => ({
      ...item,
      total: item.quantity * item.unit_price
    }));

    if (!selectedCompany) return;

    setInvoiceData(prev => ({
      ...prev,
      items: updatedItems,
      ...computeTotals(updatedItems, vatRate, ppdaRate, prev.discount_type, prev.discount_value),
    }));
  };

  const handleDiscountChange = (t: DiscountType, value: number) => {
    if (!selectedCompany) return;
    setInvoiceData(prev => ({
      ...prev,
      discount_type: t,
      discount_value: value,
      ...computeTotals(prev.items || [], vatRate, ppdaRate, t, value),
    }));
  };

  const handleVatChange = (rate: number) => {
    setVatRate(rate);
    setInvoiceData(prev => ({
      ...prev,
      ...computeTotals(prev.items || [], rate, ppdaRate, prev.discount_type, prev.discount_value),
    }));
  };

  const addNewItem = () => {
    const newItem: InvoiceItem = {
      description: '',
      quantity: 1,
      unit_price: 0,
      total: 0
    };

    const updatedItems = [...(invoiceData.items || []), newItem];
    handleItemsChange(updatedItems);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!id || !selectedCompany || !invoiceData.items || invoiceData.items.length === 0) return;

    if (!invoiceData.invoice_number?.trim()) {
      alert('Please enter an invoice number.');
      return;
    }

    setLoading(true);
    try {
      await updateInvoice(parseInt(id), { ...invoiceData, vat_rate: vatRate } as Partial<Invoice>);
      navigate(`/invoice/${id}`);
    } catch (error: any) {
      console.error('Error updating invoice:', error);
      const message =
        error?.response?.data?.error ||
        error?.response?.data?.message ||
        'Failed to update invoice. Please try again.';
      alert(message);
    } finally {
      setLoading(false);
    }
  };

  if (initialLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-gray-300"></div>
      </div>
    );
  }

  if (!selectedCompany) {
    return <div className="text-center">Please select a company</div>;
  }

  // Get the primary color from the selected company
  // Brightened in dark mode so dark company palettes stay readable.
  const primaryColor = brandColorFor(selectedCompany?.primary_color || '#4f46e5', theme === 'dark');

  // Helper to convert hex to rgba
  const hexToRgba = (hex: string, alpha: number): string => {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    if (!result) return `rgba(79, 70, 229, ${alpha})`;
    return `rgba(${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}, ${alpha})`;
  };

  const getButtonStyle = (): React.CSSProperties => ({
    backgroundColor: primaryColor,
  });

  const getInputStyle = (): React.CSSProperties => ({
    borderColor: hexToRgba(primaryColor, 0.3),
  });

  const getTextStyle = (): React.CSSProperties => ({
    color: primaryColor,
  });

  return (
    <div className={showPreview ? 'max-w-[1700px] mx-auto' : 'max-w-4xl mx-auto'}>
      <div className="mb-8 flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <button
            onClick={() => navigate(-1)}
            className="inline-flex items-center px-4 py-2 text-gray-600 hover:text-gray-900 transition-colors"
          >
            <ArrowLeft className="h-4 w-4 mr-2" />
            Back
          </button>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Edit Invoice</h1>
            <p className="text-gray-600 mt-2">
              Editing {invoiceData.invoice_number}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-3">
        <PreviewToggleButton show={showPreview} onToggle={togglePreview} />
        <button
          onClick={handleSubmit}
          disabled={loading || !invoiceData.items?.length}
          className="inline-flex items-center px-6 py-3 border border-transparent rounded-lg shadow-sm text-base font-medium text-white hover:opacity-90 focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
          style={getButtonStyle()}
        >
          {loading ? (
            <>
              <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
              Saving...
            </>
          ) : (
            <>
              <Save className="h-4 w-4 mr-2" />
              Save Changes
            </>
          )}
        </button>
        </div>
      </div>

      <div className={showPreview ? 'grid grid-cols-1 xl:grid-cols-2 gap-8 items-start' : ''}>
      <div className="space-y-6">
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <h2 className="text-xl font-semibold mb-6">Invoice Details</h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Invoice Number
              </label>
              <input
                type="text"
                value={invoiceData.invoice_number || ''}
                onChange={(e) => handleInputChange('invoice_number', e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                placeholder="e.g. EH-INV-0001"
                required
              />
              <p className="mt-1 text-xs text-gray-500">
                Auto-generated when created. Edit if needed.
              </p>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Date
              </label>
              <input
                type="date"
                value={invoiceData.date || ''}
                onChange={(e) => handleInputChange('date', e.target.value)}
                className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500`}
                required
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Payment due in
              </label>
              <UnitInput unit="days" min={1} step="1" fallback={30} value={invoiceData.due_days ?? 30} onChange={(v) => handleInputChange('due_days', v === '' ? '' : parseInt(v, 10) || 0)} />
            </div>

            <VatControl rate={vatRate} onChange={handleVatChange} defaultRate={Number(selectedCompany?.vat_rate) || 0.165} />
            <DiscountInput className="md:col-span-2" type={invoiceData.discount_type} value={invoiceData.discount_value} onChange={handleDiscountChange} />

            {selectedCompany?.template === 'supreme' && (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Title
                </label>
                <input
                  type="text"
                  value={invoiceData.title || ''}
                  onChange={(e) => handleInputChange('title', e.target.value)}
                  placeholder="e.g. Supply of branded T-shirts"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />
              </div>
            )}
          </div>
        </div>

        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <h2 className="text-xl font-semibold mb-6">Client Information</h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Client Name *
              </label>
              <input
                type="text"
                value={invoiceData.client_name || ''}
                onChange={(e) => handleInputChange('client_name', e.target.value)}
                className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500`}
                required
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Client Email
              </label>
              <input
                type="email"
                value={invoiceData.client_email || ''}
                onChange={(e) => handleInputChange('client_email', e.target.value)}
                className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500`}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Client Phone
              </label>
              <input
                type="tel"
                value={invoiceData.client_phone || ''}
                onChange={(e) => handleInputChange('client_phone', e.target.value)}
                className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500`}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Client Address
              </label>
              <textarea
                value={invoiceData.client_address || ''}
                onChange={(e) => handleInputChange('client_address', e.target.value)}
                rows={3}
                className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500`}
              />
            </div>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-semibold">Invoice Items</h2>
            <button
              onClick={addNewItem}
              className="inline-flex items-center px-4 py-2 text-white rounded-lg hover:shadow-lg hover:opacity-90 transition-all"
              style={getButtonStyle()}
            >
              <Plus className="h-4 w-4 mr-2" />
              Add Item
            </button>
          </div>

          <div className="space-y-4">
            {invoiceData.items && invoiceData.items.length > 0 ? (
              <LineItemsEditor
                items={invoiceData.items}
                onChange={handleItemsChange}
                newItem={() => ({ description: '', quantity: 1, unit_price: 0, total: 0 })}
                accent={brandColorFor(selectedCompany?.primary_color || '#4f46e5', theme === 'dark')}
              />
            ) : (
              <div className="text-center py-12 border-2 border-dashed border-gray-300 rounded-lg">
                <Calculator className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                <p className="text-gray-600 mb-4">No items added yet</p>
                <button
                  onClick={addNewItem}
                  className="inline-flex items-center px-4 py-2 text-white rounded-lg hover:opacity-90 transition-all"
                  style={getButtonStyle()}
                >
                  <Plus className="h-4 w-4 mr-2" />
                  Add Your First Item
                </button>
              </div>
            )}
          </div>

          {invoiceData.items && invoiceData.items.length > 0 && (
            <div className="mt-6 bg-gray-50 rounded-lg p-4">
              <div className="space-y-2">
                <div className="flex justify-between text-sm">
                  <span>Subtotal:</span>
                  <span className="font-medium">{formatCurrency(invoiceData.subtotal || 0)}</span>
                </div>
                {Number(invoiceData.discount_amount) > 0 && (
                  <div className="flex justify-between text-sm text-amber-700">
                    <span>Discount{invoiceData.discount_type === 'percent' ? ` (${formatNumber(Number(invoiceData.discount_value) || 0, 1)}%)` : ''}:</span>
                    <span className="font-medium">− {formatCurrency(Number(invoiceData.discount_amount))}</span>
                  </div>
                )}
                {vatRate > 0 ? (
                  <div className="flex justify-between text-sm">
                    <span>VAT ({formatNumber(vatRate * 100, 1)}%):</span>
                    <span className="font-medium">{formatCurrency(invoiceData.vat_amount || 0)}</span>
                  </div>
                ) : (
                  <div className="flex justify-between text-sm text-gray-500">
                    <span>VAT:</span>
                    <span>Not added</span>
                  </div>
                )}
                {Number(invoiceData.ppda_amount) > 0 && (
                  <div className="flex justify-between text-sm">
                    <span>PPDA ({formatNumber(ppdaRate * 100, 1)}%):</span>
                    <span className="font-medium">{formatCurrency(invoiceData.ppda_amount || 0)}</span>
                  </div>
                )}
                <div className="flex justify-between text-lg font-bold border-t pt-2" style={getTextStyle()}>
                  <span>Grand Total:</span>
                  <span>{formatCurrency(invoiceData.grand_total || 0)}</span>
                </div>
              </div>
            </div>
          )}
        </div>

        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <h2 className="text-xl font-semibold mb-6">Additional Information</h2>

          <div className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Notes
              </label>
              <textarea
                value={invoiceData.notes || ''}
                onChange={(e) => handleInputChange('notes', e.target.value)}
                rows={3}
                className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500`}
                placeholder="Any additional notes for this invoice"
              />
            </div>

          </div>
        </div>
      </div>
        {showPreview && (
          <PreviewColumn>
            <DocumentPreview watch={[invoiceData, vatRate, selectedCompany]}>
              <InvoiceDocument
                data={{ ...invoiceData, vat_rate: vatRate }}
                company={{
                  name: selectedCompany?.name || '',
                  address: selectedCompany?.address,
                  tpin: selectedCompany?.tpin,
                  bank_details: selectedCompany?.bank_details,
                  logo_url: selectedCompany?.quote_logo_url || selectedCompany?.logo_url,
                  primary_color: selectedCompany?.primary_color,
                  secondary_color: selectedCompany?.secondary_color,
                  template: selectedCompany?.template,
                  letterhead: selectedCompany?.letterhead,
                  currency: selectedCompany?.currency,
                }}
              />
            </DocumentPreview>
          </PreviewColumn>
        )}
      </div>
    </div>
  );
};

export default EditInvoice;
